'use strict';
// A selection owns its source and quantities; state.cart remains the aggregate
// of orderable part numbers for review/export and model-context inspection.
const replacementList={groups:[],nextId:1,selected:null,partPage:0,page:0,fullSelected:null,full:false,edit:null,added:null,animation:null,popupTimer:null};
const replacementOriginal={handle,bracketSelection,renderMountMenu,render,review};
function replacementSync(){const all=new Map();for(const group of replacementList.groups)for(const part of group.parts){let item=all.get(part.code);if(!item){item={code:part.code,name:part.name,unit:part.unit,qty:0,sources:[],bundle:group.parts.length>1?replacementTitle(group):''};all.set(part.code,item)}item.qty+=part.qty*group.qty;if(!item.sources.includes(group.source))item.sources.push(group.source)}state.cart=[...all.values()]}
function replacementMount(entries){const fromName=entries.map(x=>x.name).join(' ').match(/(?:—|-) (Ceiling|Fascia|Pocket|Wall|Jamb) Mount/i);if(fromName)return Object.keys(mounts).find(m=>m.toLowerCase()===fromName[1].toLowerCase());if(state.mount&&entries.every(x=>Object.values(mounts[state.mount]).includes(x.code)))return state.mount;return Object.keys(mounts).find(m=>entries.every(x=>Object.values(mounts[m]).includes(x.code)))||null}
function replacementKind(group,part){const m=mounts[group.mount];return m?Object.keys(m).find(k=>m[k]===part.code):null}
function replacementTitle(group){if(!group.mount)return group.parts[0]?.name||'Replacement part';const kinds=group.parts.map(p=>replacementKind(group,p));if(group.parts.length>1)return `Roller 100 — ${group.mount} Mount ${kinds.includes('sub')?'Bracket':'Shade Bracket'} Bundle`;return kinds[0]==='sub'?`Roller 100 — ${group.mount} Mounting Sub-Bracket`:`Roller 100 — ${group.mount} Mount ${kinds[0]==='left'?'Left':'Right'} Shade Bracket`}
function replacementUnit(group){return group.parts.length>1?'bundle':group.parts[0]?.unit||'each'}
function replacementBudget(full=false){return Math.max(390,Math.min(520,window.innerHeight-(full?330:490)))}
function replacementCap(full=false){return Math.max(2,Math.min(window.innerWidth<620?3:5,Math.floor(replacementBudget(full)/(window.innerWidth<620?120:100))))}
function replacementGroup(id){return replacementList.groups.find(g=>g.id===id)}
function replacementSnapshot(){return structuredClone(replacementList.groups)}
function replacementRestore(groups){replacementList.groups=groups;replacementList.selected=null;replacementList.fullSelected=null;replacementSync();render();if(replacementList.full&&$('#modal').open)replacementShowFull(true)}
addParts=function(entries,bundle){if(!entries.length)return;const before=replacementSnapshot(),mount=replacementMount(entries),source=state.source||'Parts directory',beforeCount=replacementList.groups.length;const previousPositions=new Map([...document.querySelectorAll('.replacement-list .replacement-row')].map(el=>[el.dataset.group,el.getBoundingClientRect().top]));let group=replacementList.groups.find(g=>g.source===source&&g.mount===mount&&(mount||g.parts[0]?.code===entries[0].code));
 if(group){for(const part of group.parts)part.qty*=group.qty;group.qty=1;for(const entry of entries){const part=group.parts.find(p=>p.code===entry.code);if(part)part.qty++;else group.parts.push({...entry,qty:1})}const gcd=(a,b)=>b?gcd(b,a%b):a;const common=group.parts.map(p=>p.qty).reduce(gcd);group.qty=common;group.parts.forEach(p=>p.qty/=common);replacementList.groups=replacementList.groups.filter(g=>g!==group)}else group={id:'R'+replacementList.nextId++,mount,source,qty:1,parts:entries.map(e=>({...e,qty:1}))};replacementList.groups.push(group);replacementList.selected=null;replacementList.partPage=0;replacementList.added=group.id;replacementList.animation={id:group.id,positions:previousPositions};replacementSync();renderCart();requestAnimationFrame(replacementAnimate);
 clearTimeout(replacementList.popupTimer);if(replacementList.groups.length>6&&replacementList.groups.length>beforeCount)replacementList.popupTimer=setTimeout(()=>{if(!replacementList.edit)replacementShowFull()},750);
 toast(bundle?`${bundle} added`:`${entries.length>1?'Parts':entries[0].code} added to your list`,()=>{replacementRestore(before);toast('Addition undone')});
};
function replacementAnimate(){const pending=replacementList.animation;if(!pending)return;const root=document.querySelector('.replacement-list');if(!root)return;replacementList.animation=null;const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;for(const row of root.querySelectorAll('.replacement-row')){if(row.dataset.group===pending.id){row.classList.add('replacement-added');if(!reduced)row.animate([{opacity:0,transform:'translateY(10px)'},{opacity:1,transform:'translateY(0)'}],{duration:340,easing:'cubic-bezier(.2,.7,.25,1)'})}else if(!reduced&&pending.positions.has(row.dataset.group)){const shift=pending.positions.get(row.dataset.group)-row.getBoundingClientRect().top;row.animate([{transform:`translateY(${shift}px)`},{transform:'translateY(0)'}],{duration:340,easing:'cubic-bezier(.2,.7,.25,1)'})}}setTimeout(()=>{replacementList.added=null;document.querySelectorAll('.replacement-confirmation').forEach(el=>el.textContent='Newest additions at the bottom')},5000)}
function replacementRows(groups,full=false){return `<div class="replacement-rows" ${!full&&replacementList.selected?'inert':''}>${groups.map(g=>btn(`<span class="replacement-row-copy"><strong>${esc(replacementTitle(g))}</strong><small>${esc(g.source)}</small></span><span class="replacement-row-qty">Qty ${g.qty}</span>${icon('ChevronRight','replacement-row-arrow')}`,'replacement-detail','replacement-row',`data-group="${g.id}" data-full="${full}" aria-expanded="${(full?replacementList.fullSelected:replacementList.selected)===g.id}"`)).join('')}</div>`}
function replacementDetails(group,full=false){const budget=replacementBudget(full),per=budget<405?1:budget<470?2:3,pages=Math.ceil(group.parts.length/per);replacementList.partPage=Math.min(replacementList.partPage,pages-1);const parts=group.parts.slice(replacementList.partPage*per,(replacementList.partPage+1)*per),index=replacementList.groups.indexOf(group),unit=replacementUnit(group);return `<section class="replacement-detail" aria-label="Selected replacement item"><div class="replacement-detail-top"><span>Part details</span><span>Item ${index+1} of ${replacementList.groups.length}</span></div><h3>${esc(replacementTitle(group))}</h3><p class="replacement-source">${esc(group.source)}</p><div class="replacement-parts"><h4>${group.parts.length>1?'Included in each bundle':'Part details'}</h4>${parts.map(p=>`<div class="replacement-part"><div><span>${esc(replacementKind(group,p)==='left'?'Left shade bracket':replacementKind(group,p)==='right'?'Right shade bracket':replacementKind(group,p)==='sub'?group.mount+' sub-bracket':p.name)}</span><strong>${esc(p.code)}</strong></div><span>${p.qty} ${esc(p.unit)}</span></div>`).join('')}${group.parts.length>1?'<p>Ordered as separate part numbers.</p>':''}${pages>1?`<div class="replacement-part-pages"><span>Contents ${replacementList.partPage+1} / ${pages}</span>${btn('Previous','replacement-part-prev','link',replacementList.partPage?'':'disabled')}${btn('Next','replacement-part-next','link',replacementList.partPage<pages-1?'':'disabled')}</div>`:''}</div><div class="replacement-controls"><div class="replacement-qty-label">Qty <div class="replacement-qty">${btn('−','replacement-qty','',`data-group="${group.id}" data-delta="-1" aria-label="Decrease quantity"`)}<output>${group.qty}</output>${btn('+','replacement-qty','',`data-group="${group.id}" data-delta="1" aria-label="Increase quantity"`)}</div><span>${unit}${group.qty===1?'':'s'}</span></div><div class="replacement-text-actions">${link('Change','replacement-change',`data-group="${group.id}" data-full="${full}"`)}${link('Remove','replacement-remove',`data-group="${group.id}" data-full="${full}"`)}</div></div><div class="replacement-detail-nav"><span>Browse items</span><div>${btn('Previous','replacement-item-prev','small',`data-group="${group.id}" data-full="${full}" ${index?'':'disabled'}`)}${btn('Next','replacement-item-next','small',`data-group="${group.id}" data-full="${full}" ${index<replacementList.groups.length-1?'':'disabled'}`)}</div></div>${full?reference(pageReference()+'-REPLACEMENT-LIST-'+group.id+'-DETAIL','replacement-detail-reference'):''}</section>`}
function replacementEmptyContent(){const instruction=state.page==='directory'?'Add parts from the directory.':state.page==='components'?'Choose replacement parts from the component list.':'Add replacement parts as you browse.';return `<div class="replacement-empty replacement-empty-compact">${icon('ListPlus')}<h3>No parts added yet</h3><p>${instruction} They’ll appear here for review.</p><div class="replacement-empty-note"><svg class="ui-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><circle cx="12" cy="12" r="9"/><path d="M12 11v6M12 7v1"/></svg><span>Your list stays with you as you browse.</span></div></div>`}
function replacementEmptyFooter(){return `<footer class="replacement-footer replacement-empty-footer">${btn('Review & Submit','review','primary','disabled')}<p>Available after you add a part.</p></footer>`}
function replacementEmptyCard(){return `<aside class="panel cart replacement-list replacement-list-empty" aria-label="Replacement list"><header class="replacement-header"><h2>Replacement list</h2><span class="replacement-empty-count" aria-label="0 items">0</span></header>${replacementEmptyContent()}${replacementEmptyFooter()}</aside>`}
cart=function(){if(!replacementList.groups.length)return replacementEmptyCard();const list=replacementList.groups,selected=replacementGroup(replacementList.selected),cap=replacementCap();return `<aside class="panel cart replacement-list" aria-label="Replacement list" style="--replacement-body:${replacementBudget()}px;--replacement-cap:${cap}"><header class="replacement-header"><h2>Replacement list</h2><p class="replacement-confirmation" role="status">${replacementList.added?'✓ Added to your list':'Newest additions at the bottom'}</p></header><div class="replacement-body">${list.length?replacementRows(list.slice(-cap)):`<div class="replacement-empty">${icon('ListPlus')}<h3>Start adding parts</h3><p>Parts you add will stay here as you browse.</p></div>`}${selected?`<div class="replacement-sheet-mask"></div><div class="replacement-sheet">${replacementDetails(selected)}</div>`:''}</div><footer class="replacement-footer">${btn(`<span><b>${list.length}</b> items (see all)</span>${list.length>cap?`<small>Latest ${cap} shown</small>`:''}`,'replacement-full','replacement-see-all',list.length?'':'disabled')}${btn(selected?'Close Detail':'Review & Submit',selected?'replacement-detail-close':'review','primary',list.length?'':'disabled')}</footer></aside>`};
renderCart=function(){const c=$('.cart');if(c)c.outerHTML=cart();if(state.page==='review')render();else stampFeatures();if(replacementList.full&&$('#modal').open&&!replacementList.edit)replacementShowFull(true)};
const replacementStamp=stampFeatures;stampFeatures=function(){replacementStamp();const selected=replacementGroup(replacementList.selected),ref=document.querySelector('.replacement-list > .feature-reference');if(selected&&ref)ref.innerHTML=referenceContent(pageReference()+'-REPLACEMENT-LIST-'+selected.id+'-DETAIL')};
const replacementRender=render;render=function(){replacementRender();if(replacementList.animation)requestAnimationFrame(replacementAnimate)};
function replacementFullBody(){if(!replacementList.groups.length)return `<section class="replacement-full-panel replacement-list-empty">${replacementEmptyContent()}${replacementEmptyFooter()}</section>`;const groups=replacementList.groups,cap=replacementCap(true),pages=Math.max(1,Math.ceil(groups.length/cap));replacementList.page=Math.max(0,Math.min(replacementList.page,pages-1));const selected=replacementGroup(replacementList.fullSelected),chunk=groups.slice(replacementList.page*cap,(replacementList.page+1)*cap);return `<section class="replacement-full-panel" style="--replacement-body:${replacementBudget(true)}px;--replacement-cap:${cap}"><div class="replacement-body">${selected?replacementDetails(selected,true):groups.length?replacementRows(chunk,true):'<div class="replacement-empty"><h3>Start adding parts</h3></div>'}</div><footer class="replacement-full-footer"><nav class="replacement-pager" aria-label="Replacement list pages"><span>${selected?'Item details':groups.length?`${replacementList.page*cap+1}–${Math.min((replacementList.page+1)*cap,groups.length)} of ${groups.length} items`:'0 items'}</span><div>${btn('Previous','replacement-page-prev','small',selected||!replacementList.page?'disabled':'')}${btn('Next','replacement-page-next','small',selected||replacementList.page>=pages-1?'disabled':'')}</div></nav>${btn(selected?'Close Detail':'Review & Submit',selected?'replacement-full-detail-close':'replacement-review','primary',groups.length?'':'disabled')}</footer></section>`}
function replacementShowFull(refresh=false){clearTimeout(replacementList.popupTimer);if(!refresh){replacementList.fullSelected=null;replacementList.partPage=0;replacementList.page=Math.ceil(replacementList.groups.length/replacementCap(true))-1}replacementList.full=true;openModal(modalFrame('Full replacement list',replacementFullBody(),'M-REPLACEMENT-LIST-FULL'),refresh);$('#modal').classList.add('replacement-full-dialog')}
review=function(){return `<main class="page replacement-review-page">${crumbs('Review & Submit')}${title('Review & Submit','Check your selections, part numbers, and quantities.')}<section class="panel replacement-review-panel">${replacementFullBody()}</section><div class="footer-actions"><p class="meta">Prototype only · Downloads the supplied sample CSV.</p><div class="row">${btn('Add more parts','directory')}${btn('Download CSV','replacement-download-csv','primary',replacementList.groups.length?'':'disabled')}</div></div></main>`};
function replacementRefresh(){replacementSync();renderCart();if(state.page==='review'&&!replacementList.full)render()}
function replacementBeginEdit(group,fromFull){clearTimeout(replacementList.popupTimer);replacementList.edit={id:group.id,fromFull,snapshot:Object.fromEntries(['mount','source','line','expanded','includeShade','includeSub','side','selectionOrigin'].map(k=>[k,state[k]]))};$('#modal').classList.remove('replacement-full-dialog');replacementList.full=false;state.mount=group.mount;state.source=group.source;state.selectionOrigin='replacement-edit';if(group.mount){const kinds=group.parts.map(p=>replacementKind(group,p));state.includeShade=kinds.includes('left')||kinds.includes('right');state.includeSub=kinds.includes('sub');state.side=kinds.includes('left')&&kinds.includes('right')?'Both':kinds.includes('left')?'Left':'Right';showBracketSelection()}else openModal(modalFrame('Change quantity',`<p>${esc(replacementTitle(group))}</p><p class="meta small-gap">Ordering unit: ${esc(group.parts[0].unit)}</p><label class="label" for="replacement-edit-qty">Quantity</label><input id="replacement-edit-qty" type="number" min="1" max="999" value="${group.qty}">${btn('Save changes','replacement-save','primary','style="margin-top:20px"')}`,'M-REPLACEMENT-CHANGE-QUANTITY'));$('#modal').classList.add('replacement-config-dialog')}
function replacementEndEdit(save=false){const edit=replacementList.edit;if(!edit)return;const group=replacementGroup(edit.id);if(save&&group){if(group.mount){const oldParts=new Map(group.parts.map(p=>[replacementKind(group,p),p.qty]));const entries=partEntries(state.mount);group.parts=entries.filter((p,i)=>i===2?state.includeSub:state.includeShade&&(state.side==='Both'||(i===0?'Left':'Right')===state.side)).map((p,i)=>({...p,qty:oldParts.get(p.code===mounts[state.mount].left?'left':p.code===mounts[state.mount].right?'right':'sub')||1}));group.mount=state.mount}else group.qty=Math.max(1,Math.min(999,Math.floor(Number($('#replacement-edit-qty')?.value)||1)))}replacementList.edit=null;Object.assign(state,edit.snapshot);$('#modal').classList.remove('replacement-config-dialog');$('#modal').close();replacementSync();render();if(edit.fromFull){replacementList.fullSelected=edit.id;replacementList.full=true;replacementShowFull(true)}if(save)toast('Replacement selection updated')}
bracketSelection=function(){let html=replacementOriginal.bracketSelection();if(replacementList.edit)html=html.replace('data-action="add-selected"','data-action="replacement-save"').replace('Add selected parts','Save changes');return html};
renderMountMenu=function(){if(!replacementList.edit)return replacementOriginal.renderMountMenu();const s=menuState;if(s.expanded){const m=s.expanded;openModal(modalFrame(m+' Mount',`<div class="replacement-mount-focus"><p class="meta">Part numbers for this mounting condition</p>${partEntries(m).map(p=>`<div class="replacement-mount-part"><span>${esc(p.name)}</span><div class="row"><b class="partcode">${p.code}</b>${copy(p.code)}</div></div>`).join('')}${btn('Use this mount','select-mount','primary',`data-mount="${m}"`)}</div>`,'M-REPLACEMENT-MOUNT-'+slug(m)));return}openModal(modalFrame('Mount type',`${Object.keys(mounts).map(m=>`<div class="mount-row"><div class="mount-heading">${btn(m+' Mount','select-mount',s.selected===m?'selected':'',`data-mount="${m}"`)}${btn('Details','mount-expand','link detail',`data-mount="${m}"`)}</div></div>`).join('')}<div class="bundle"><div><h3>Need a complete bracket bundle?</h3><p>${esc(s.selected||state.mount)} mount · Left + right on-shade brackets and mounting sub-bracket kit.</p><small>Added as three separate part numbers.</small></div>${btn('Use complete bracket bundle','replacement-complete-bundle','primary')}</div>`,'M-REPLACEMENT-MOUNT-TYPE'))};
handle=function(action,el){const group=replacementGroup(el?.dataset.group),full=el?.dataset.full==='true';switch(action){
 case 'replacement-detail':replacementList.partPage=0;if(full){replacementList.fullSelected=group.id;if(replacementList.full)replacementShowFull(true);else render()}else{replacementList.selected=group.id;renderCart()}return;
 case 'replacement-detail-close':replacementList.selected=null;renderCart();return;
 case 'replacement-full-detail-close':replacementList.fullSelected=null;replacementRefresh();return;
 case 'replacement-full':replacementShowFull();return;
 case 'replacement-qty':group.qty=Math.max(1,Math.min(999,group.qty+Number(el.dataset.delta)));replacementRefresh();return;
 case 'replacement-remove':{const before=replacementSnapshot();replacementList.groups=replacementList.groups.filter(g=>g!==group);replacementList.selected=null;replacementList.fullSelected=null;replacementRefresh();toast('Selection removed',()=>replacementRestore(before));return}
 case 'replacement-item-prev':case 'replacement-item-next':{const index=replacementList.groups.indexOf(group)+(action.endsWith('next')?1:-1);const next=replacementList.groups[index];if(next){replacementList[full?'fullSelected':'selected']=next.id;replacementList.partPage=0;replacementRefresh()}return}
 case 'replacement-part-prev':case 'replacement-part-next':replacementList.partPage+=action.endsWith('next')?1:-1;replacementRefresh();return;
 case 'replacement-page-prev':case 'replacement-page-next':replacementList.page+=action.endsWith('next')?1:-1;replacementRefresh();return;
 case 'replacement-change':replacementBeginEdit(group,full);return;
 case 'replacement-save':if(replacementList.edit&&(!state.mount||state.includeShade||state.includeSub))replacementEndEdit(true);return;
 case 'replacement-complete-bundle':state.mount=menuState.selected||state.mount;state.includeShade=true;state.includeSub=true;state.side='Both';showBracketSelection();return;
 case 'replacement-review':replacementList.full=false;replacementList.fullSelected=null;$('#modal').close();navigate('review');return;
 case 'replacement-download-csv':{if(!replacementList.groups.length)return;const download=document.createElement('a');download.href='part-replace-parts.csv';download.download='part-replace-parts (30).csv';document.body.appendChild(download);download.click();download.remove();return}
 }
 if(replacementList.edit){if(action==='close'){replacementEndEdit(false);return}if(action==='menu-bundle'){handle('replacement-complete-bundle',el);return}if(action==='quick-part'){state.mount=el.dataset.mount;state.includeShade=el.dataset.kind!=='sub';state.includeSub=el.dataset.kind==='sub';state.side=el.dataset.kind==='left'?'Left':'Right';showBracketSelection();return}}
 if(action==='review'){replacementList.fullSelected=null;replacementList.page=Math.max(0,Math.ceil(replacementList.groups.length/replacementCap(true))-1)}
 replacementOriginal.handle(action,el);
};
$('#modal').addEventListener('close',()=>{if($('#modal').open)return;$('#modal').classList.remove('replacement-full-dialog','replacement-config-dialog');replacementList.full=false;if(replacementList.edit)replacementEndEdit(false)});
let replacementLayout='';window.addEventListener('resize',()=>{const key=[replacementCap(),replacementCap(true),replacementBudget(),replacementBudget(true)].join(':');if(key!==replacementLayout){replacementLayout=key;if(document.querySelector('.replacement-list')||state.page==='review')renderCart()}});
render();
